package io.lumine.mythic.lib.api.crafting.recipes.vmp; import java.util.*; public abstract class ThreeSlotMapping extends VanillaInventoryMapping { public int getMainWidth(int r){return 1;} public int getMainHeight(int c){return 1;} public int getMainSlot(int x,int y){if(x!=0||y!=0)throw outOfBounds(x,y);return 0;} public int getMainInventoryStart(){return 0;} public int getMainInventoryWidth(){return 1;} public int getMainInventoryHeight(){return 1;} public int getResultWidth(int r){return 1;} public int getResultHeight(int c){return 1;} public int getResultSlot(int x,int y){if(x!=0||y!=0)throw outOfBounds(x,y);return 2;} public int getResultInventoryStart(){return 2;} public int getResultInventoryWidth(){return 1;} public int getResultInventoryHeight(){return 1;} public boolean isResultSlot(int s){return s==2;} public int getSideWidth(String n,int r){validateSide(n);return 1;} public int getSideHeight(String n,int c){validateSide(n);return 1;} public int getSideSlot(String n,int x,int y){validateSide(n);if(x!=0||y!=0)throw outOfBounds(x,y);return 1;} public int getSideInventoryStart(String n){validateSide(n);return 1;} public int getSideInventoryWidth(String n){validateSide(n);return 1;} public int getSideInventoryHeight(String n){validateSide(n);return 1;} public boolean mainIsResult(){return false;} }
